<?php
/** Proof — fixed bid, credit notes, write-off, aging, statement (spec "Proof", 5): M1's invoice INV-00002; void → the milestone accepted and WIP again, the lines kept as text; INV-00003 issued; a credit note drafted, lines, issued CN-00001, applied 2500 → owed 7500; unapply; apply again; write off with a reason; the aging and the statement agree with the proof's figures. And receipts the engagement does not share. */
require __DIR__ . '/lib.php';
$w = billing_world(); $beta = $w['beta'];
$marco = as_member(27); $bea = as_member(28); $priya = as_member(26); $ann = as_member(29);
$betaClient = (int) one('SELECT client_id FROM engagements WHERE id = :e', ['e' => $beta]);
$acmeInvoice = (int) one("SELECT id FROM invoices WHERE number = 'INV-00001'");
$acmeInvoice > 0 or exit(fwrite(STDERR, "run issue.php first\n") ?: 2);

echo "1. M1 accepted; its invoice INV-00002\n";
[$c, $b] = act($marco, '/engagements/milestones/save.php', ['engagement' => $beta, 'name' => 'SMOKE M1 Discovery', 'amount' => '10000']);
$m1 = (int) $b['record_id'];
[$c, $b] = act($marco, '/engagements/milestones/save.php', ['engagement' => $beta, 'name' => 'SMOKE M2 Build', 'amount' => '8000']);
$m2 = (int) $b['record_id'];
act($marco, '/engagements/milestones/deliver.php', ['milestone' => $m1]);
[$c, $b] = act($marco, '/engagements/milestones/accept.php', ['milestone' => $m1, 'acceptance_note' => 'SMOKE Jo (AP) by email']);
ok($c === 200 && wip($beta) === '10000.00', 'M1 accepted: 10,000.00 of WIP on the fixed bid');
$since = last_activity_id();
[$c, $b] = draft($marco, $beta, ['period_end' => '2026-09-30']);
$d2 = (int) $b['record_id'];
ok($c === 200 && $b['counts']['milestone_lines'] === 1 && $b['counts']['time_lines'] === 0 && $b['total'] === '10000.00' && lines_of($d2)[0]['kind'] === 'milestone' && lines_of($d2)[0]['description'] === 'Milestone: SMOKE M1 Discovery' && inv($d2)['po_number'] === 'PO-77', 'a draft for the fixed bid pulls the accepted milestone as one line of 10,000.00 (the PO the engagement\'s)');
[$c, $b] = act($bea, '/invoices/issue.php', ['invoice' => $d2]);
ok($c === 200 && $b['number'] === 'INV-00002' && (string) one('SELECT status FROM milestones WHERE id = :m', ['m' => $m1]) === 'invoiced' && (bool) one("SELECT ct_item_billed('milestone', :m)", ['m' => $m1]), 'issued INV-00002: the milestone is marked invoiced');

echo "2. Void releases everything; the lines stay as text\n";
[$c, $b] = act($bea, '/invoices/void.php', ['invoice' => $d2]);
ok($c === 422 && isset(fields($b)['reason']), 'invoice_void without a reason: 422 on the field');
[$c, $b] = act($marco, '/invoices/void.php', ['invoice' => $d2, 'reason' => 'x']);
ok($c === 403, 'a Manager: 403');
$since = last_activity_id();
[$c, $b] = act($bea, '/invoices/void.php', ['invoice' => $d2, 'reason' => 'SMOKE issued to the wrong entity']);
$i = inv($d2);
ok($c === 200 && $i['status'] === 'void' && $i['void_reason'] === 'SMOKE issued to the wrong entity' && (int) $i['voided_by'] === 28 && $i['voided_at'] !== null && $i['number'] === 'INV-00002', 'invoice_void: void with its reason, the number kept (INV-00002 is never reused)');
ok((string) one('SELECT status FROM milestones WHERE id = :m', ['m' => $m1]) === 'accepted' && !(bool) one("SELECT ct_item_billed('milestone', :m)", ['m' => $m1]) && wip($beta) === '10000.00' && items_of($d2) === 0, 'the milestone is accepted again and WIP again (10,000.00); no backing item remains');
ok(count(lines_of($d2)) === 1 && lines_of($d2)[0]['description'] === 'Milestone: SMOKE M1 Discovery' && $i['total'] === '10000.00', 'the line is kept as text on the void invoice');
$log = activity('invoice.void', $since);
$after = json_decode((string) $log[0]['after'], true);
ok(count($log) === 1 && $after['amount'] === '10000.00' && $after['currency'] === 'USD' && $after['reason'] === 'SMOKE issued to the wrong entity' && $after['number'] === 'INV-00002' && (int) $log[0]['invoice_id'] === $d2 && (int) $log[0]['engagement_id'] === $beta, 'invoice.void logged: number, amount, currency, reason, the keys');
[$c, $b] = act($bea, '/invoices/void.php', ['invoice' => $d2, 'reason' => 'again']);
ok($c === 422 && msg($b) === 'Invoice INV-00002 is already void', 'voiding twice: "Invoice INV-00002 is already void"');
[$c, $b] = act($bea, '/payments/save.php', ['invoice' => $d2, 'amount' => '5']);
ok($c === 422 && str_contains(msg($b), 'is void and takes no payment'), 'a void invoice takes no payment');
[$c, $b] = act($bea, '/invoices/send.php', ['invoice' => $d2]);
ok($c === 422 && str_contains(msg($b), 'is void and is not sent'), 'nor is it sent (' . msg($b) . ')');

echo "3. INV-00003, overdue; a credit note\n";
[$c, $b] = draft($marco, $beta, ['period_end' => '2026-09-30', 'issue_date' => '2026-08-01', 'due_date' => '2026-08-31']);
$d3 = (int) $b['record_id'];
[$c, $b] = act($bea, '/invoices/issue.php', ['invoice' => $d3]);
ok($c === 200 && $b['number'] === 'INV-00003' && $b['total'] === '10000.00', 'INV-00003 issued for the same milestone (issued 2026-08-01, due 2026-08-31)');
$since = last_activity_id();
[$c, $b] = act($marco, '/credit-notes/save.php', ['invoice' => $d3, 'reason' => 'x']);
ok($c === 403, 'a Manager drafts no credit note: 403');
[$c, $b] = act($bea, '/credit-notes/save.php', ['invoice' => $acmeInvoice, 'reason' => 'x']);
$ac = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $ac > 0, 'a credit note may be drafted against a paid invoice (a correction after the fact)');
act($bea, '/credit-notes/delete.php', ['credit_note' => $ac]);
$cnSeq = (int) one("SELECT next_value FROM document_sequences WHERE kind = 'credit_note'");
[$c, $b] = act($bea, '/credit-notes/save.php', ['invoice' => $d3, 'reason' => 'SMOKE scope reduced by agreement']);
$cn1 = (int) $b['record_id'];
$n = cn($cn1);
ok($c === 200 && $n['status'] === 'draft' && $n['number'] === null && (int) $n['client_id'] === $betaClient && (int) $n['engagement_id'] === $beta && (int) $n['invoice_id'] === $d3 && trim($n['currency']) === 'USD' && $n['reason'] === 'SMOKE scope reduced by agreement', 'credit_note_draft: a draft with no number, the invoice\'s client, engagement and currency copied');
[$c, $b] = act($bea, '/credit-notes/issue.php', ['credit_note' => $cn1]);
ok($c === 422 && msg($b) === 'A credit note for nothing is not issued', 'issuing a note with no lines: "A credit note for nothing is not issued"');
[$c, $b] = act($bea, '/credit-notes/lines/save.php', ['credit_note' => $cn1, 'description' => 'SMOKE Phase 2 descoped', 'unit_price' => '2,500.00']);
$cl = (int) $b['line_id'];
ok($c === 200 && cn($cn1)['total'] === '2500.00' && cn($cn1)['balance'] === '2500.00', 'credit_note_line_save: one line of 2,500.00 — the note totals 2,500.00 (the database added it)');
[$c, $b] = act($bea, '/credit-notes/lines/save.php', ['credit_note' => $cn1, 'description' => '', 'unit_price' => '-3']);
ok($c === 422 && isset(fields($b)['description']) && isset(fields($b)['unit_price']), 'a blank line and a negative price: 422 naming both');
[$c, $b] = act($bea, '/credit-notes/issue.php', ['credit_note' => $cn1]);
$n = cn($cn1);
ok($c === 200 && $b['number'] === 'CN-00001' && $n['status'] === 'issued' && (int) $n['issued_by'] === 28, 'credit_note_issue: CN-00001, gapless');
ok(str_contains(refused('UPDATE credit_note_lines SET unit_price = 1 WHERE id = :l', ['l' => $cl]), 'change only while it is a draft'), 'an issued credit note\'s lines are immutable (the database\'s words)');
[$c, $b] = act($bea, '/credit-notes/apply.php', ['credit_note' => $cn1, 'invoice' => $d3, 'amount' => '3000']);
ok($c === 422 && msg($b) === 'Credit note CN-00001 is 2500.00; applying 3000.00 more would exceed it', 'applying more than the note holds: refused in words (' . msg($b) . ')');
[$c, $b] = act($bea, '/credit-notes/apply.php', ['credit_note' => $cn1, 'invoice' => $acmeInvoice, 'amount' => '100']);
ok($c === 422 && str_contains(msg($b), 'is paid and takes no credit') || str_contains(msg($b), 'belongs to another client'), 'applying it to another client\'s invoice: refused (' . msg($b) . ')');
$since = last_activity_id();
[$c, $b] = act($bea, '/credit-notes/apply.php', ['credit_note' => $cn1, 'invoice' => $d3, 'amount' => '2500']);
$i = inv($d3);
ok($c === 200 && $i['amount_credited'] === '2500.00' && $i['balance_due'] === '7500.00' && $i['status'] === 'partially_paid' && cn($cn1)['amount_applied'] === '2500.00' && cn($cn1)['balance'] === '0.00', 'credit_note_apply 2,500.00: INV-00003 owes 7,500.00 (partially paid); the note is fully applied');
$log = activity('credit_note.apply', $since);
$after = json_decode((string) $log[0]['after'], true);
ok(count($log) === 1 && $after['amount'] === '2500.00' && $after['currency'] === 'USD' && $after['invoice_number'] === 'INV-00003' && $after['number'] === 'CN-00001' && (int) $log[0]['invoice_id'] === $d3, 'credit_note.apply logged: number, amount, currency, the invoice');
[$c, $b] = act($bea, '/credit-notes/void.php', ['credit_note' => $cn1, 'reason' => 'x']);
ok($c === 422 && str_contains(msg($b), 'is applied to an invoice; unapply it first'), 'voiding an applied credit note: "…is applied to an invoice; unapply it first"');
[$c, $b] = act($bea, '/invoices/void.php', ['invoice' => $d3, 'reason' => 'x']);
ok($c === 422 && str_contains(msg($b), 'has payments or credits applied'), 'voiding an invoice with a credit applied: refused');
$since = last_activity_id();
[$c, $b] = act($bea, '/credit-notes/unapply.php', ['credit_note' => $cn1, 'invoice' => $d3]);
$i = inv($d3);
ok($c === 200 && $i['amount_credited'] === '0.00' && $i['balance_due'] === '10000.00' && $i['status'] === 'issued' && cn($cn1)['balance'] === '2500.00', 'credit_note_unapply: owed 10,000.00 again, the note whole');
ok(count(activity('credit_note.unapply', $since)) === 1, 'credit_note.unapply logged');
[$c, $b] = act($bea, '/credit-notes/unapply.php', ['credit_note' => $cn1, 'invoice' => $d3]);
ok($c === 422 && str_contains(msg($b), 'is not applied'), 'unapplying what is not applied: refused');
[$c, $b] = act($bea, '/credit-notes/apply.php', ['credit_note' => $cn1, 'invoice' => $d3, 'amount' => '2500']);
ok($c === 200 && inv($d3)['balance_due'] === '7500.00', 'apply again: owed 7,500.00');
$log = activity('credit_note.issue', 0);
ok(count($log) === 1 && json_decode((string) $log[0]['after'], true)['amount'] === '2500.00' && json_decode((string) $log[0]['after'], true)['currency'] === 'USD' && json_decode((string) $log[0]['after'], true)['number'] === 'CN-00001', 'credit_note.issue carries number, amount and currency');
// a second note: drafted, issued and voided
[$c, $b] = act($bea, '/credit-notes/save.php', ['invoice' => $d3, 'reason' => 'SMOKE a goodwill note']);
$cn2 = (int) $b['record_id'];
act($bea, '/credit-notes/lines/save.php', ['credit_note' => $cn2, 'description' => 'SMOKE goodwill', 'unit_price' => '100']);
[$c, $b] = act($bea, '/credit-notes/issue.php', ['credit_note' => $cn2]);
ok($c === 200 && $b['number'] === 'CN-00002', 'a second note is CN-00002');
$since = last_activity_id();
[$c, $b] = act($bea, '/credit-notes/void.php', ['credit_note' => $cn2, 'reason' => 'SMOKE not agreed']);
$log = activity('credit_note.void', $since);
ok($c === 200 && cn($cn2)['status'] === 'void' && cn($cn2)['void_reason'] === 'SMOKE not agreed' && count($log) === 1 && json_decode((string) $log[0]['after'], true)['amount'] === '100.00' && json_decode((string) $log[0]['after'], true)['currency'] === 'USD', 'credit_note_void: an unapplied note is voided with a reason; logged with amount and currency');
[$c, $b] = act($bea, '/credit-notes/apply.php', ['credit_note' => $cn2, 'invoice' => $d3, 'amount' => '50']);
ok($c === 422 && str_contains(msg($b), 'is void, not issued'), 'a void note cannot be applied');
ok((int) one("SELECT next_value FROM document_sequences WHERE kind = 'credit_note'") === $cnSeq + 2, 'two numbers taken, none lost (the deleted draft burned none)');

echo "4. The credit note screens\n";
[$c, $dd] = screen($bea, '/credit-notes/' . $cn1);
ok($c === 200 && $dd['credit_note']['number'] === 'CN-00001' && $dd['credit_note']['amount_applied'] === '2500.00' && count($dd['credit_note']['applications']) === 1 && $dd['credit_note']['lines'][0]['line_total'] === '2500.00' && $dd['may']['unapply'] === true && $dd['may']['void'] === false, 'credit-note-view: the lines, the application, Unapply offered, Void not');
$r = page($bea, '/credit-notes/' . $cn1);
ok($r['code'] === 200 && str_contains($r['body'], 'id="application-' . $d3 . '-unapply-btn"') && str_contains($r['body'], 'id="credit-total-applied"'), 'the page renders');
[$c, $dd] = screen($bea, '/credit-notes/?status=issued');
ok($c === 200 && count($dd['credit_notes']) === 1 && $dd['credit_notes'][0]['number'] === 'CN-00001', 'the list filtered by status');
$r = page($bea, '/credit-notes/new?invoice=' . $d3);
ok($r['code'] === 200 && str_contains($r['body'], 'id="credit-note-form-invoice"') && str_contains($r['body'], 'INV-00003'), 'the add form against an invoice names it');
[$c, $b] = act($marco, '/credit-notes/lines/save.php', ['credit_note' => $cn1, 'description' => 'x', 'unit_price' => '1']);
ok($c === 403, 'a Manager: no credit lines (403)');

echo "5. The aging and the statement agree\n";
[$c, $dd] = screen($bea, '/reports/ar-aging');
$row = array_values(array_filter($dd['rows'], static fn ($r) => $r['client']['client_id'] === $betaClient))[0] ?? [];
ok($c === 200 && count($dd['rows']) === 1 && $row['current'] === '0.00' && $row['d31_60'] === '7500.00' && $row['total'] === '7500.00' && $row['open_invoices'] === 1 && $dd['totals']['USD']['total'] === '7500.00', 'who owes us: SMOKE Beta owes 7,500.00, 35 days past due — the 31–60 bucket; INV-00001 (paid) and INV-00002 (void) are not in it');
[$c, $dd] = screen($bea, '/reports/ar-aging?as_of=2026-08-15');
ok($c === 200 && $dd['rows'][0]['d31_60'] === '0.00' && $dd['rows'][0]['current'] === '7500.00', 'as of 2026-08-15 the same balance was still current');
$r = req('GET', '/reports/ar-aging?format=csv', ['jar' => $bea]);
ok($r['code'] === 200 && str_starts_with($r['headers'], 'HTTP') && preg_match('/^Content-Type: text\/csv/mi', $r['headers']) === 1 && str_contains($r['body'], 'Client,Currency,Current') && str_contains($r['body'], '"SMOKE Beta",USD,0.00,0.00,7500.00,0.00,0.00,7500.00,1'), 'the CSV carries the same row');
[$c, $dd] = screen($ann, '/reports/ar-aging');
ok($c === 200 && $dd['totals']['USD']['total'] === '7500.00', 'Finance reads the aging too');
[$c, $dd] = screen($marco, '/reports/ar-aging');
ok($c === 403, 'a Manager does not see the firm\'s aging (ct_ar_aging is not scoped by engagement, so the screen is Billing\'s and the wall-less readers\'): 403');
$r = page($bea, '/reports/ar-aging');
ok($r['code'] === 200 && str_contains($r['body'], 'id="ar-aging-table"') && str_contains($r['body'], 'id="aging-total-USD"') && str_contains($r['body'], 'id="ar-aging-csv-btn"'), 'the page renders: the table, the total row, the CSV button');
[$c, $st] = screen($bea, '/clients/' . $betaClient . '/statement');
$rows = $st['lines'];
ok($c === 200 && count($rows) === 2 && $rows[0]['kind'] === 'invoice' && $rows[0]['number'] === 'INV-00003' && $rows[0]['charge'] === '10000.00' && $rows[0]['running_balance'] === '10000.00' && $rows[1]['kind'] === 'credit_note' && $rows[1]['number'] === 'CN-00001' && $rows[1]['credit'] === '2500.00' && $rows[1]['running_balance'] === '7500.00' && $st['closing'] === ['USD' => '7500.00'], 'the statement of SMOKE Beta: INV-00003 charged 10,000.00, CN-00001 credited 2,500.00, the running balance 7,500.00 — the aging\'s figure; the void invoice and the void note are not on it');
[$c, $st2] = screen($bea, '/clients/' . $w['client'] . '/statement');
ok($c === 200 && array_column($st2['lines'], 'kind') === ['invoice', 'payment', 'payment'] && $st2['closing'] === ['USD' => '0.00'] && $st2['lines'][1]['credit'] === '1000.00' && $st2['lines'][2]['credit'] === '1359.00', 'the statement of SMOKE Acme: INV-00001 2,359.00, payments 1,000.00 and 1,359.00 (the voided cheque is not there): balance 0.00');
[$c, $st3] = screen($bea, '/clients/' . $w['client'] . '/statement?from=' . date('Y-m-d', time() + 86400));
ok($c === 200 && $st3['lines'] === [], 'a period after today: nothing on it');
[$c, $st3] = screen($bea, '/clients/' . $betaClient . '/statement?to=2026-09-30');
ok($c === 200 && count($st3['lines']) === 1 && $st3['lines'][0]['number'] === 'INV-00003' && $st3['closing'] === ['USD' => '10000.00'], 'a period to 2026-09-30: only the invoice (10,000.00) — the credit note came later');
$r = page($bea, '/clients/' . $betaClient . '/statement');
ok($r['code'] === 200 && str_contains($r['body'], 'id="client-statement-table"') && str_contains($r['body'], 'id="statement-closing-USD"') && str_contains($r['body'], 'id="client-statement-send-btn"'), 'the page renders with Send');
[$c, $st] = screen($marco, '/clients/' . $betaClient . '/statement');
ok($c === 403, 'a Manager has no statement either: 403');
[$c, $st] = screen($ann, '/clients/' . $betaClient . '/statement');
ok($c === 200 && count($st['lines']) === 2 && $st['may']['send'] === false, 'Finance reads the statement; Send is Billing\'s (may.send false)');

echo "6. Write off\n";
[$c, $b] = act($bea, '/invoices/write-off.php', ['invoice' => $d3]);
ok($c === 422 && isset(fields($b)['reason']), 'invoice_write_off without a reason: 422 on the field');
[$c, $b] = act($marco, '/invoices/write-off.php', ['invoice' => $d3, 'reason' => 'x']);
ok($c === 403, 'a Manager: 403');
$since = last_activity_id();
[$c, $b] = act($bea, '/invoices/write-off.php', ['invoice' => $d3, 'reason' => 'SMOKE the client is insolvent']);
$i = inv($d3);
ok($c === 200 && $i['status'] === 'written_off' && $i['write_off_reason'] === 'SMOKE the client is insolvent' && (int) $i['written_off_by'] === 28 && $i['written_off_at'] !== null, 'invoice_write_off: written off with the reason, by Bea');
ok((string) one('SELECT status FROM milestones WHERE id = :m', ['m' => $m1]) === 'invoiced' && (bool) one("SELECT ct_item_billed('milestone', :m)", ['m' => $m1]) && wip($beta) === '0', 'the items stay billed: the milestone is still invoiced; nothing is unbilled');
$log = activity('invoice.write_off', $since);
$after = json_decode((string) $log[0]['after'], true);
ok(count($log) === 1 && $after['amount'] === '7500.00' && $after['currency'] === 'USD' && $after['reason'] === 'SMOKE the client is insolvent' && (int) $log[0]['invoice_id'] === $d3, 'invoice.write_off logged: amount = the balance forgiven (7,500.00), currency, reason');
[$c, $b] = act($bea, '/invoices/write-off.php', ['invoice' => $d3, 'reason' => 'again']);
ok($c === 422 && str_contains(msg($b), 'is written_off and is not written off'), 'writing it off twice: refused in words');
[$c, $b] = act($bea, '/payments/save.php', ['invoice' => $d3, 'amount' => '5']);
ok($c === 422 && str_contains(msg($b), 'takes no payment'), 'a written-off invoice takes no payment');
[$c, $dd] = screen($bea, '/reports/ar-aging');
ok($c === 200 && $dd['rows'] === [], 'who owes us: nobody now');
[$c, $st] = screen($bea, '/clients/' . $betaClient . '/statement');
ok($c === 200 && end($st['lines'])['kind'] === 'write_off' && end($st['lines'])['credit'] === '7500.00' && $st['closing'] === ['USD' => '0.00'], 'the statement ends with the write-off of 7,500.00: balance 0.00');

echo "7. A receipt the engagement does not share\n";
q('UPDATE engagements SET share_receipts_with_client = false WHERE id = :e', ['e' => $beta]);
$jpg = jpeg_file('beta.jpg');
[$c, $b] = upload($priya, '/expenses/save.php', ['engagement' => $beta, 'date' => '2026-09-20', 'category' => category('meals'), 'amount' => '90.00', 'description' => 'SMOKE beta dinner', 'submit' => '1'], 'file', $jpg, 'beta.jpg');
$bx = (int) $b['record_id'];
[$c, $b] = act($marco, '/expenses/approve.php', ['expense' => $bx]);
[$c, $b] = draft($marco, $beta, ['period_end' => '2026-09-30']);
$d4 = (int) $b['record_id'];
$since = last_activity_id();
[$c, $b] = act($bea, '/invoices/issue.php', ['invoice' => $d4]);
$bAtt = (int) one("SELECT id FROM attachments WHERE record_type = 'expense' AND record_id = :x", ['x' => $bx]);
ok($c === 200 && $b['number'] === 'INV-00004' && inv($d4)['total'] === '90.00' && json_decode((string) activity('invoice.issue', $since)[0]['after'], true)['receipts_shared'] === 0 && !(bool) one('SELECT client_visible FROM attachments WHERE id = :a', ['a' => $bAtt]), 'INV-00004 (the dinner): the engagement does not share receipts, so none is shared (receipts_shared 0)');
bill_contact($betaClient, 'ap@beta.example.invalid');
act($bea, '/invoices/send.php', ['invoice' => $d4]);
$tok = token_in((string) (outbox('invoice', $d4)[0]['body'] ?? ''));
$h = visitor('/i/' . $tok)['body'];
ok(str_contains($h, 'SMOKE beta dinner') && !str_contains($h, '/attachment/') && visitor('/i/' . $tok . '/attachment/' . $bAtt)['code'] === 404, 'the client sees the expense line but no receipt, and the receipt door refuses it');
q('UPDATE engagements SET share_receipts_with_client = NULL WHERE id = :e', ['e' => $beta]);
finish();
